import {initialLayout,actions,findRule,label,outputKey,assign,setOutput,exportConfig,parseImport,eventKey} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const example=await fetch('example.json').then(r=>r.json());let state=parseImport(example),mode=1,selected='A',listening=false,capturing=false;
try{const saved=JSON.parse(localStorage.getItem('clickshift-v1'));if(saved){parseImport(saved.rule);if(saved.layout&&Number.isInteger(saved.vendor)&&Number.isInteger(saved.product))state=saved;}}catch{}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem('clickshift-v1',JSON.stringify(state));}catch{toast('Browser storage unavailable. Export JSON to keep your changes.');$('.local').textContent='Changes not saved in this browser';}}
function current(){return findRule(state,state.layout[selected],mode);}
function render(){if(!state.layout[selected])selected=Object.keys(state.layout)[0];const m=current(),out=m?.to;$('#selected-badge').textContent=selected;$('#selected-title').textContent=selected+' button';$('#input-key').textContent=state.layout[selected];$('#preview-from').textContent=selected;$('#preview-to').textContent=label(out);$('#preview-key').textContent=outputKey(out);$('#signal-mode').textContent=mode?'ANKI':'VIDEO';$$('[data-mode]').forEach(b=>b.classList.toggle('active',+b.dataset.mode===mode));$$('.remote [data-button]').forEach(b=>b.classList.toggle('selected',b.dataset.button===selected));const select=$('#action');select.replaceChildren();[['pass','Pass through (no remap)'],...actions.map((a,i)=>[String(i),a[0]]),['toggle','Switch Video / Anki mode'],['custom','Custom keyboard shortcut']].forEach(([value,text])=>select.add(new Option(text,value)));let index=actions.findIndex(a=>JSON.stringify([a[1]])===JSON.stringify(out));select.value=!out?'pass':out[0]?.set_variable?'toggle':index>=0?String(index):'custom';const basic=out?.length===1&&out[0].key_code;if(out&&index<0&&!out[0].set_variable&&!basic){select.add(new Option('Imported action (preserved)','preserved'));select.value='preserved';}$('#custom-fields').hidden=select.value!=='custom';$('#custom-key').value=basic?out[0].key_code:'';$$('.modifiers input').forEach(c=>c.checked=!!out?.[0]?.modifiers?.includes(c.value));const grid=$('#mapping-grid');grid.replaceChildren();Object.entries(state.layout).forEach(([name,key])=>{const b=document.createElement('button');b.className='mapping-card'+(name===selected?' active':'');const top=document.createElement('div'),badge=document.createElement('b'),input=document.createElement('code'),text=document.createElement('span');badge.textContent=name;input.textContent=key;top.append(badge,input);text.textContent=label(findRule(state,key,mode)?.to);b.append(top,text);b.onclick=()=>{selected=name;capturing=false;render();};grid.append(b);});$('#map-count').textContent=Object.keys(state.layout).length+' buttons';$('#capture').textContent=capturing?'Press remote button…':'◎ Capture input';}
function updateListen(){ $('#listen-status').textContent=listening?'Listening for key presses':'Input listening paused';$('#listen').textContent=listening?'Pause listening':'Start listening';$('#listen-dot').classList.toggle('on',listening);}
$('#listen').onclick=()=>{listening=!listening;capturing=false;updateListen();render();};$('#capture').onclick=()=>{capturing=true;listening=true;updateListen();render();toast('Press the physical '+selected+' button. Escape cancels.');};
$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=+b.dataset.mode;render();});$$('.remote [data-button]').forEach(b=>b.onclick=()=>{selected=b.dataset.button;capturing=false;render();b.classList.add('pressed');setTimeout(()=>b.classList.remove('pressed'),200);});
window.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||!listening)return;if(capturing&&e.code==='Escape'){capturing=false;render();return;}const key=eventKey(e);if(!key||e.metaKey||e.ctrlKey||e.altKey)return;e.preventDefault();if(e.repeat)return;if(capturing){try{assign(state,selected,key);capturing=false;save();toast('Input captured for '+selected);}catch(err){toast(err.message);}render();return;}const entry=Object.entries(state.layout).find(([,k])=>k===key);$('#last-input').textContent=key;$('#input-status').textContent='Keyboard event received · '+key;if(entry){selected=entry[0];const m=findRule(state,key,mode);$('#last-output').textContent=label(m?.to);$$('.remote [data-button]').filter(b=>b.dataset.button===selected).forEach(b=>b.classList.add('pressed'));if(m?.to[0]?.set_variable?.name==='8bitdo_mode')mode=m.to[0].set_variable.value;render();}else{$('#last-output').textContent='Unassigned · select a button to capture';}});
window.addEventListener('keyup',()=>$$('.pressed').forEach(b=>b.classList.remove('pressed')));window.addEventListener('blur',()=>{listening=false;capturing=false;updateListen();render();$$('.pressed').forEach(b=>b.classList.remove('pressed'));});
$('#action').onchange=()=>{const v=$('#action').value;if(v==='preserved')return;if(v==='custom'){setOutput(state,state.layout[selected],mode,[{key_code:'spacebar'}]);save();render();$('#action').value='custom';$('#custom-fields').hidden=false;$('#custom-key').focus();return;}setOutput(state,state.layout[selected],mode,v==='pass'?null:v==='toggle'?[{set_variable:{name:'8bitdo_mode',value:mode?0:1}}]:[structuredClone(actions[+v][1])]);save();render();};
function custom(){const key=$('#custom-key').value.trim();const allowed=/^(?:[a-z]|[0-9]|f(?:[1-9]|1[0-9]|2[0-4])|spacebar|return_or_enter|escape|tab|delete_or_backspace|delete_forward|up_arrow|down_arrow|left_arrow|right_arrow|home|end|page_up|page_down|hyphen|equal_sign|open_bracket|close_bracket|backslash|semicolon|quote|comma|period|slash|grave_accent_and_tilde|caps_lock)$/;if(!allowed.test(key)){toast('Enter a supported Karabiner key, such as a, spacebar, or up_arrow.');return;}const modifiers=$$('.modifiers input:checked').map(c=>c.value);setOutput(state,state.layout[selected],mode,[{key_code:key,...(modifiers.length?{modifiers}:{})}]);save();render();$('#action').value='custom';$('#custom-fields').hidden=false;}
$('#custom-key').onchange=custom;$$('.modifiers input').forEach(c=>c.onchange=custom);
function modal(title,html){capturing=false;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}$('#close-modal').onclick=()=>$('#modal').close();
$('#guide').onclick=()=>modal('A few presses. A perfect fit.',`<ol><li>Pair your 8BitDo with macOS in <strong>keyboard mode</strong>. This app reads keyboard events while its tab is focused; it does not pair Bluetooth devices.</li><li>Temporarily disable your existing Karabiner remappings. Select a pictured button, choose <strong>Capture input</strong>, and press that physical button. Repeat to calibrate the suggested layout.</li><li>Pick an output for each button in both tabs. Start toggles the exported <code>8bitdo_mode</code> variable; its initial value is 0 (Video). The tab selector only changes the preview.</li><li>Export the JSON and save it in <code>~/.config/karabiner/assets/complex_modifications/</code>. In Karabiner, open <strong>Complex Modifications → Add predefined rule</strong> and enable Clickshift.</li></ol><p>Keyboard events do not identify the physical device. Exported rules use the device IDs from your example (11720 / 36888); verify yours in Karabiner EventViewer. Inputs and mappings stay in this browser.</p><p><a href="https://karabiner-elements.pqrs.org/docs/json/" target="_blank" rel="noreferrer">Karabiner configuration reference ↗</a></p><button id="guide-import">Import a compatible JSON file</button>`),$('#guide').addEventListener('click',()=>$('#guide-import').onclick=()=>$('#file').click());
$('#export').onclick=()=>{modal('Your configuration, ready to go.',`<p>Both modes are included. Save this file in <code>~/.config/karabiner/assets/complex_modifications/</code>, then enable it in Karabiner’s Complex Modifications.</p><div class="device-fields"><label>Vendor ID<input id="vendor" type="number" min="0" max="65535"></label><label>Product ID<input id="product" type="number" min="0" max="65535"></label></div><textarea id="json-output" readonly aria-label="Generated Karabiner JSON"></textarea><div class="dialog-actions"><button class="primary" id="download">↓ Download JSON</button><button id="copy">Copy JSON</button></div>`);$('#vendor').value=state.vendor;$('#product').value=state.product;const refresh=()=>$('#json-output').value=JSON.stringify(exportConfig(state),null,2);refresh();['vendor','product'].forEach(k=>$('#'+k).onchange=()=>{const input=$('#'+k),n=Number(input.value);if(!input.value||!Number.isInteger(n)||n<0||n>65535){toast('Enter a device ID between 0 and 65535.');input.value=state[k];return;}state[k]=n;save();refresh();});$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([$('#json-output').value],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='clickshift-8bitdo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Configuration downloaded');};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#json-output').value);toast('JSON copied');}catch{$('#json-output').select();toast('Select the JSON and copy it manually.');}};};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async()=>{try{const f=$('#file').files[0];if(!f)return;if(f.size>1000000)throw Error('Please choose a JSON file under 1 MB.');const next=parseImport(JSON.parse(await f.text()));state=next;selected='A';save();render();$('#modal').close();toast('Configuration imported. Calibrate the physical button layout.');}catch(err){toast(err.message);}$('#file').value='';};$('#reset').onclick=()=>{modal('Reset your layout?',`<p>This replaces your saved mappings with the supplied example. Export first if you want to keep your changes.</p><button class="primary" id="confirm-reset">Reset to example</button>`);$('#confirm-reset').onclick=()=>{state=parseImport(example);mode=1;selected='A';save();render();$('#modal').close();toast('Example restored');};};render();
